// Production is not the repository. An admin added this value live, to unblock
// planners during an incident, and it exists in no branch. Level 3 lab 7 retrofits it.
List<Metadata.Metadata> found = Metadata.Operations.retrieve(
    Metadata.MetadataType.CustomField,
    new List<String>{ 'Installation__c.Status__c' }
);
if (!found.isEmpty()) {
    Metadata.CustomField field = (Metadata.CustomField) found.get(0);
    Boolean already = false;
    if (field.valueSet != null && field.valueSet.valueSetDefinition != null) {
        for (Metadata.CustomValue value : field.valueSet.valueSetDefinition.value) {
            if (value.fullName == 'Needs Reinspection') {
                already = true;
            }
        }
        if (!already) {
            Metadata.CustomValue added = new Metadata.CustomValue();
            added.fullName = 'Needs Reinspection';
            added.label = 'Needs Reinspection';
            added.isActive = true;
            field.valueSet.valueSetDefinition.value.add(added);
            Metadata.DeployContainer container = new Metadata.DeployContainer();
            container.addMetadata(field);
            Metadata.Operations.enqueueDeployment(container, null);
        }
    }
}
System.debug('Needs Reinspection drift applied');

// Level 3 lab 8 needs findings that are real rather than staged. Inactive people
// still holding a licence is the most common one on any org older than a year.
List<User> stale = [SELECT Id, LastLoginDate FROM User WHERE IsActive = true AND Profile.UserLicense.Name = 'Salesforce' LIMIT 5];
System.debug('Users monitoring will look at: ' + stale.size());

